// DESCRIPTION: Check if an iron pickaxe is already in the inventory by scanning inventory for 'iron_pickaxe'
async function checkForIronPickaxe(bot) {
    const inventory = bot.inventory.items();
    for (let item of inventory) {
        if (item.name === 'iron_pickaxe') {
            return true;
        }
    }
    return false;
}

// DESCRIPTION: Main function to perform the task
async function checkIronPickaxe(bot) {
    let found = await checkForIronPickaxe(bot);
    if (found) {
        console.log('Iron pickaxe found in inventory.');
    } else {
        console.log('Iron pickaxe not found in inventory.');
    }
}

