// DESCRIPTION: Free at least four inventory slots by tossing full stacks of surplus items, then excess cobblestone stacks, moving away after each drop.
async function tossClutterForIron(bot, minFree = 4) {
    if (bot.interrupt_code) return;

    bot.__safeToToss = [
        'pink_petals',
        'sweet_berries',
        'raw_copper',
        'diorite',
        'andesite',
        'oak_sapling',
        'gravel',
        'birch_log',
        'granite',
    ];
    bot.__depositCandidates = [];
    await tossClutter(bot, minFree);
    if (bot.interrupt_code) return;

    const surplusNames = [
        'sweet_berries',
        'raw_copper',
        'diorite',
        'andesite',
        'oak_sapling',
        'gravel',
        'pink_petals',
        'birch_log',
        'granite',
    ];

    for (let pass = 0; pass < 12 && bot.inventory.emptySlotCount() < minFree; pass++) {
        if (bot.interrupt_code) return;
        let tossedThisPass = false;
        for (const name of surplusNames) {
            if (bot.interrupt_code) return;
            if (bot.inventory.emptySlotCount() >= minFree) break;
            const it = bot.inventory.items().find((x) => x.name === name);
            if (!it || it.count <= 0) continue;
            const ok = await tossItem(bot, name, it.count);
            if (bot.interrupt_code) return;
            if (!ok) continue;
            tossedThisPass = true;
            await moveAway(bot, 10);
            if (bot.interrupt_code) return;
            await wait(bot, 400);
        }
        if (!tossedThisPass) break;
    }

    const keepCobble = 128;
    for (let i = 0; i < 15 && bot.inventory.emptySlotCount() < minFree; i++) {
        if (bot.interrupt_code) return;
        const inv = getInventoryCounts(bot);
        if ((inv.cobblestone || 0) <= keepCobble) break;
        const it = bot.inventory.items().find((x) => x.name === 'cobblestone');
        if (!it) break;
        const ok = await tossItem(bot, 'cobblestone', it.count);
        if (bot.interrupt_code) return;
        if (!ok) break;
        await moveAway(bot, 10);
        if (bot.interrupt_code) return;
        await wait(bot, 400);
    }

    const empty = bot.inventory.emptySlotCount();
    if (empty < minFree && !bot.interrupt_code) {
        log(bot, `FAILED tossClutterForIron: only ${empty} empty (target ${minFree}); no chest to deposit`);
    } else if (!bot.interrupt_code) {
        log(bot, `tossClutterForIron: ${empty} empty slot(s) (target ${minFree})`);
    }
    return empty;
}
