// DESCRIPTION: Craft itemName until the inventory holds at least target, walking to the nearest crafting_table if one is needed; returns true on success.
async function craftItem(bot, itemName, target = 1) {
    const have = () => getInventoryCounts(bot)[itemName] || 0;
    if (!have()) {
        const recipe = bot.recipes.find(r => r.output.name === itemName);
        if (!recipe) {
            log(bot, 'FAILED: No recipe found for ' + itemName);
            return false;
        }
        const materials = recipe.ingredients.map(i => i.name);
        for (const material of materials) {
            if (!have(material)) {
                if (!(await collectBlock(bot, material, 1))) {
                    log(bot, 'FAILED: Could not collect ' + material);
                    return false;
                }
            }
        }
    }
    if (!getNearestBlock(bot, 'crafting_table', 6) && !getInventoryCounts(bot)['crafting_table']) {
        if (!(await ensureCraftingTable(bot))) {
            log(bot, 'FAILED: Could not ensure crafting table');
            return false;
        }
    }
    for (let i = 0; i < target && have() < target; i++) {
        if (bot.interrupt_code) return false;
        if (!(await craftRecipe(bot, itemName, 1))) break;
    }
    return have() >= target;
}

